import React, { useState, useEffect } from "react";
import {
  TextField,
  Button,
  Box,
  Select,
  MenuItem,
  Paper,
  Typography,
  IconButton,
  Stack,
} from "@mui/material";
import { AddCircleOutline, RemoveCircleOutline } from "@mui/icons-material";
import axios from "axios";

const ContactForm = () => {
  const [fields, setFields] = useState([]);
  const [valueFields, setVlaueFields] = useState([{ namesList: [""] }]);

  const updateValue = (index, key, newValue) => {
    const updatedNameFields = [...valueFields];
    updatedNameFields[index] = { ...updatedNameFields[index], [key]: newValue };
    setVlaueFields(updatedNameFields);
  };

  const addValueField = () => {
    setVlaueFields([...valueFields, { namesList: [""] }]);
  };

  const removeValueField = (index) => {
    setVlaueFields(valueFields.filter((_, i) => i !== index));
  };
  // Fetch existing form data from API
  useEffect(() => {
    const fetchFormData = async () => {
      try {
        const response = await axios.get("http://localhost:5000/contact-form");
        setFields(response.data.length > 0 ? response.data : [{ id: "1", Type: "input", value: [""], label: "Name" }]);
      } catch (error) {
        console.error("Error fetching form data:", error);
      }
    };
    fetchFormData();
  }, []);

  // Handle changes in form fields
  const handleChange = (index, key, newValue) => {
    const updatedFields = [...fields];

    if (key === "value") {
      updatedFields[index][key] = Array.isArray(newValue) ? newValue : [newValue];
    } else {
      updatedFields[index][key] = newValue;
    }

    setFields(updatedFields);
  };

  // Add a new field
  const addField = () => {
    setFields([...fields, { id: `${fields.length + 1}`, Type: "input", value: [""], label: "" }]);
  };

  // Remove a field
  const removeField = (index) => {
    setFields(fields.filter((_, i) => i !== index));
  };

  // Submit form
  const handleSubmit = async () => {
    try {
      await axios.post("http://localhost:5000/contact-form", fields);
      console.log("Form submitted successfully");
    } catch (error) {
      console.error("Error submitting form:", error);
    }
  };

  return (
    <Paper sx={{ p: 3, mx: "auto", m: '0', maxHeight :'500px', overflowY :'auto' }} className="Edit">
      <Typography variant="h6" gutterBottom>
        Contact Form
      </Typography>

      {fields.map((field, index) => (
        <Box key={field.id} display="flex" flexDirection="column" gap={2} mb={2}>
          {/* Field Type Selection */}
          <Select
            value={field.Type}
            onChange={(e) => handleChange(index, "Type", e.target.value)}
            sx={{ minWidth: 120 }}
          >
            <MenuItem value="input">Input</MenuItem>
            <MenuItem value="textarea">Textarea</MenuItem>
            <MenuItem value="select">Dropdown</MenuItem>
          </Select>

          {/* Field Label */}
          <TextField
            fullWidth
            label="Label"
            variant="outlined"
            value={field.label}
            onChange={(e) => handleChange(index, "label", e.target.value)}
          />

          {/* Field Value */}
          {field.Type === "select" ? (
            <Stack spacing={2}>
      {valueFields.map((field, index) => (
        <Stack key={index} direction="row" spacing={1} alignItems="center">
          <TextField
            label="value"
            fullWidth
            variant="outlined"
            value={field.namesList.join(", ")} // Show as comma-separated names
            onChange={(e) => updateValue(index, "namesList", e.target.value.split(","))}
          />
          <Button variant="contained" color="error" onClick={() => removeValueField(index)} disabled={valueFields.length === 1}>
            Remove
          </Button>
        </Stack>
      ))}
      <Button variant="contained" onClick={addValueField}>
        Add Name Field
      </Button>
    </Stack>
          ) : (
            <TextField
              label="Value"
              variant="outlined"
              value={field.value?.join(", ")} // Show as comma-separated values
              onChange={(e) => handleChange(index, "value", e.target.value.split(","))}
            />
          )}

          <IconButton sx={{width :'50px', margin: 'auto'}} onClick={() => removeField(index)} color="error">
            <RemoveCircleOutline />
          </IconButton>
        </Box>
      ))}
      <Stack width='100%' justifyContent='center' alignItems='center' spacing={2}>
      <Button  onClick={addField} startIcon={<AddCircleOutline />} variant="outlined">
        Add Field
      </Button>

      <Button onClick={handleSubmit} variant="contained" sx={{ background :'var(--primary-bg)' }}>
        Submit
      </Button>
      </Stack>
    </Paper>
  );
};

export default ContactForm;
